lessons.solution_code:
from dataclasses import dataclass

@dataclass
class Pair:
    left: str
    right: str

    def swap(self) -> 'Pair':
        return Pair(self.right, self.left)

tests.unittest_code:
def test_pair_swap(self):
    p = Pair('a', 'b').swap()
    self.assertEqual((p.left, p.right), ('b', 'a'))
